'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Button from '../../Elements/Button';
import Modal from '../../Elements/Modal';
import EditModal from './EditModal';
import { Admin } from './types';
import AdminTable from './AdminTable';
import axios from 'axios';

const API_URL = 'http://localhost:3000/managers';

export default function AdminManager() {
  const router = useRouter();
  const RESTAURANT_ID = 1;
  const [admins, setAdmins] = useState<Admin[]>([]);
  const [deleteModal, setDeleteModal] = useState(false);
  const [editModal, setEditModal] = useState(false);
  const [selectedAdmin, setSelectedAdmin] = useState<Admin | null>(null);
  const [successModal, setSuccessModal] = useState(false);
  const [loading, setLoading] = useState(false);
  const [newUser, setNewUser] = useState({ username: '', password: '', email: '', phone_number: '', role: 'manager', restaurant_id: 1, status: 'active' });

  useEffect(() => {
    fetchManagers();
  }, []);

  const fetchManagers = async () => {
    setLoading(true);
    try {
      const response = await axios.get<Admin[]>(`${API_URL}/${RESTAURANT_ID}`);
      setAdmins(response.data);
    } catch (error) {
      console.error('Failed to fetch managers:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async (updatedAdmin: Admin) => {
    setLoading(true);
    try {
      const response = await axios.put(`${API_URL}/manager/${updatedAdmin.user_id}`, updatedAdmin);
      setAdmins(admins.map(admin => 
        admin.user_id === updatedAdmin.user_id ? updatedAdmin : admin
      ));
      setEditModal(false);
      setSuccessModal(true);
    } catch (error) {
      console.error('Failed to update manager:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async () => {
    setLoading(true);
    try {
      const response = await axios.post<Admin>(`${API_URL}`, newUser);
      setAdmins([...admins, response.data]);
      setNewUser({ username: '', password: '', email: '', phone_number: '', role: 'manager', restaurant_id: 1, status: 'active' });
      setSuccessModal(true);
    } catch (error) {
      console.error('Failed to create manager:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (managerId: number) => {
    setLoading(true);
    try {
      const response = await axios.delete(`${API_URL}/${managerId}`);
      setAdmins(admins.filter(admin => admin.user_id !== managerId));
      setDeleteModal(false);
      setSuccessModal(true);
    } catch (error) {
      console.error('Failed to delete manager:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6 max-w-4xl mx-auto mt-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold underline">VIEW ADMIN</h1>
        <Button
          label="CREATE NEW ADMIN"
          onClick={() => {
            setEditModal(true);
          }}
          style={{
            backgroundColor: 'transparent',
            color: 'black',
            border: '1px solid black'
          }}
        />
      </div>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <AdminTable 
          admins={admins}
          onEdit={(admin) => {
            setSelectedAdmin(admin);
            setEditModal(true);
          }}
          onDelete={(admin) => {
            setSelectedAdmin(admin);
            setDeleteModal(true);
          }}
        />
      )}

      <EditModal
        admin={selectedAdmin}
        isOpen={editModal}
        onClose={() => setEditModal(false)}
        onSave={handleEdit}
      />

      <Modal
        isOpen={deleteModal}
        onClose={() => setDeleteModal(false)}
        title="Delete Admin?"
      >
        <div className="flex justify-center gap-4">
          <Button
            label="DELETE"
            onClick={() => handleDelete(selectedAdmin?.user_id || 0)}
            style={{
              backgroundColor: 'white',
              color: 'black',
              border: '1px solid black'
            }}
          />
          <Button
            label="CANCEL"
            onClick={() => setDeleteModal(false)}
            style={{
              backgroundColor: 'white',
              color: 'black',
              border: '1px solid black'
            }}
          />
        </div>
      </Modal>

      <Modal
        isOpen={successModal}
        onClose={() => setSuccessModal(false)}
        title={selectedAdmin ? "Admin Updated" : "Update Success"}
      >
        <div className="flex justify-center">
          <Button
            label="CLOSE"
            onClick={() => setSuccessModal(false)}
            style={{
              backgroundColor: 'white',
              color: 'black',
              border: '1px solid black'
            }}
          />
        </div>
      </Modal>

      <form onSubmit={handleCreate}>
        {/* Form fields for newUser */}
        <button type="submit">Create User</button>
      </form>
    </div>
  );
} 